"""Ledger entries and the parser for the plain-text ledger format."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal, localcontext

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")
_LINE_BREAK_RE = re.compile(r"\r\n|\r|\n")
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line of the ledger is malformed. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str


def is_field(text):
    """True if ``text`` is one field as the parser reads it: non-empty, no space or tab."""
    return bool(text) and not _SEPARATOR_RE.search(text)


def parse_date(text):
    """Parse a strict ``YYYY-MM-DD`` string into a date; raise ValueError if invalid."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    year, month, day = int(text[:4]), int(text[5:7]), int(text[8:10])
    if not 1 <= month <= 12:
        raise ValueError("invalid date %r (no such month)" % text)
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Parse an amount with at most two decimals into a Decimal."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError(
            "invalid amount %r (expected a number with at most two decimals)" % text
        )
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of Entry objects, in file order."""
    entries = []
    # A single leading byte-order mark is not ledger text (the CLI decodes with utf-8-sig).
    if text.startswith("﻿"):
        text = text[1:]
    # Only \n, \r\n and a lone \r end a line; form feed, U+2028 and friends are
    # ordinary text (str.splitlines() would split on them too).
    lines = _LINE_BREAK_RE.split(text)
    if lines[-1] == "":
        lines.pop()
    for number, raw in enumerate(lines, start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        fields = _SEPARATOR_RE.split(line, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected 'DATE CATEGORY AMOUNT [NOTE]', got %r" % line
            )
        date_text, category, amount_text = fields[:3]
        note = fields[3].strip() if len(fields) == 4 else ""
        try:
            date = parse_date(date_text)
            amount = parse_amount(amount_text)
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        entries.append(Entry(date, category.lower(), amount, note))
    return entries


def format_amount(amount):
    """Format an amount with exactly two decimals (never ``-0.00``)."""
    with localcontext() as ctx:
        ctx.prec = 1000
        cents = amount.quantize(_CENT)
    if not cents:
        cents = abs(cents)
    return str(cents)


def format_entry(entry):
    """Canonical ledger line for an entry (no trailing newline)."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
"""Totals and filtering over lists of entries."""

from decimal import Decimal, localcontext


def _sum(amounts):
    with localcontext() as ctx:
        ctx.prec = 1000
        return sum(amounts, Decimal("0"))


def balance(entries):
    """Total of all amounts (``Decimal(0)`` for no entries)."""
    return _sum(e.amount for e in entries)


def _group(entries, key):
    groups = {}
    for entry in entries:
        groups.setdefault(key(entry), []).append(entry.amount)
    return {name: _sum(amounts) for name, amounts in groups.items()}


def by_category(entries):
    """Dict of lower-case category -> total."""
    return _group(entries, lambda e: e.category)


def by_month(entries):
    """Dict of ``YYYY-MM`` -> total."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching all given filters, in input order.

    ``category`` is compared case-insensitively; ``since`` and ``until`` are
    inclusive dates. ``None`` means no filter.
    """
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
